const path = (slug: string) => slug === "overview" ? "/" : `/${slug}`;

function Tag({ children }: { children: React.ReactNode }) { return <span className="tag">{children}</span>; }
function SectionHead({ eyebrow, title, note }: { eyebrow: string; title: string; note?: string }) {
  return <div className="section-head"><div className="eyebrow">{eyebrow}</div><h2>{title}</h2>{note && <p>{note}</p>}</div>;
}
function Placeholder({ label = "TBD", note }: { label?: string; note?: string }) { return <span className="placeholder" title={note || "Pending research"}>{label}</span>; }
function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <section className={`panel ${className}`}>{children}</section>; }
function Next({ slug, label }: { slug: string; label: string }) { return <Link className="next-link" href={path(slug)}><span>Next: {label}</span><ArrowUpRight size={18} /></Link>; }
function ResearchNote() { return <div className="research-note"><strong>ILLUSTRATIVE · ASSUMPTION / ESTIMATE · AS OF {websiteData.as_of}</strong><span>Current preferred planning case uses assumed B200/H200/L40S task shares and five hypothetical members totaling 3.5 MIT reference demand units. The 25 MW figure defines a possible expandable total-facility envelope, not an approved full build. Modeled power is design input, not average use or a site-specific utility commitment.</span></div>; }
const legacyBase = websiteData.scenario_outputs.find(row => row.year === 2030 && row.case === "base")!;
const planningCases = decisionData.planning_revision.architecture_cases;
const planningBase = planningCases.find(row => row.mix === "planning_base" && row.year === "2030" && row.case === "base")!;
const categoryLabels: Record<string,string> = { training:"Training",fine_tuning_rl:"Fine-tuning / RL",scientific_ai_hpc:"Scientific AI / HPC",biomedical_private_ai:"Biomedical / private AI",student_faculty_inference:"Student / faculty inference",coding_agents:"Coding / agents",robotics:"Robotics",inference:"General inference + coding agents" };
const mixLabels: Record<string,string> = { mid_tier_heavy:"More mid-tier", planning_base:"Planning base", high_end_heavy:"More high-end" };
function Step2Note() { return <div className="step2-note"><strong>STEP 2 ACCOUNTING RULE · {step2Data.as_of}</strong><span>Each modeled device-hour is assigned to one primary compute task. Biomedical and robotics are nonadditive tags; coding agents are an inference subtype with distinct incremental requests assumed. The B200/H200/L40S task split and all MW outputs remain illustrative.</span><a href="https://orcd-docs.mit.edu/running-jobs/requesting-resources/" target="_blank" rel="noreferrer">MIT resource guide</a></div>; }

function Overview() {
  const staged = decisionData.planning_revision.phased_underwriting_summary.find(row => row.case === "base")!;
  const kpis = [
    ["Expandable planning envelope", "25 MW", "Total facility input · not a build approval"],
    ["2030 → 2033 capacity", "12 → 15 MW", "Modeled staged colo commitment · unquoted"],
    ["2030 planning base", `${Number(planningBase.facility_design_mw).toFixed(2)} MW`, "Three-tier GPU assumption"],
    ["Selected US parcel", "TBD", "Four unranked inquiry regions"],
    ["Staged colo + cloud NPV", `$${(Number(staged.cost_npv_usd)/1e9).toFixed(3)}bn`, "12 → 15 MW model · unquoted"],
  ];
  return <><ResearchNote/><div className="hero"><div className="hero-top"><span className="hero-kicker">INVESTMENT COMMITTEE WORKING FILE</span><Tag>Preferred planning case</Tag></div><h2>University Consortium<br /><em>AI Data Center</em></h2><p>Use 25 MW as an uncommitted expandable design envelope. Inquire about a modeled 12 MW total-facility colo phase in 2030 and a conditional 15 MW phase in 2033. Test a 70% controlled colo / 30% eligible cloud allocation of annual task hours from 2030; 2027–2029 use cloud as a transition. Parcel, contract and capital approval remain open.</p><div className="hero-bottom"><span>Confirmed power definition</span><strong>25 MW</strong><span>Total facility design input · expandable ceiling</span></div></div><div className="kpi-grid">{kpis.map(([label,value,note])=><Panel key={label} className="kpi"><span>{label}</span><strong>{value}</strong><small>{note}</small></Panel>)}</div><div className="phase1-callout"><div><span>CURRENT PREFERRED · 2030 BASE</span><strong>{Number(planningBase.facility_design_mw).toFixed(2)} MW</strong></div><p>The three-tier B200/H200/L40S planning mix assigns 63.3% of original reference work to high-end classes and 36.7% to L40S-class devices. These shares and throughput conversions are assumptions, not measured member demand. The 70% on-site allocation equates to 9.26 MW of modeled 2030 base load within a 12 MW facility commitment; it does not describe measured hourly peaks. The older all-high-end model at {legacyBase.facility_design_mw.toFixed(2)} MW remains a separate stress comparison. <Link href="/architecture">Review the mix <ArrowUpRight size={14}/></Link></p></div><div className="two-col"><Panel><SectionHead eyebrow="CURRENT PLANNING RECOMMENDATION" title="Approve the next stage of inquiry" note="This is a concept and phasing decision, not authority to purchase a parcel or build the full envelope."/><div className="decision-list">{[["DEMAND", "Obtain member commitments and representative task benchmarks"],["POWER", "Ask for first-phase and 25 MW expansion dates at named US parcels"],["DELIVERY", "Price a 70% annual-hour colo allocation and 30% eligible cloud share"],["SECURITY", "Approve restricted datasets only in a qualified environment"],["PHASING", "Test 12 MW in 2030, then 15 MW in 2033 if evidence supports it"]].map(([a,b])=><div key={a}><b>{a}</b><span>{b}</span></div>)}</div></Panel><Panel className="dark-panel"><div className="eyebrow">EXECUTION GATE · STILL OPEN</div><h2>Stage capital as evidence arrives</h2><ol><li>Member minimum use commitments and GPU-tier trials</li><li>Named parcel with written staged power, fiber, water and permits</li><li>Dataset-level approval for any restricted work</li><li>Comparable cloud, dedicated, colo and own terms</li><li>Affordable low-use, delay, refresh and power-price cases</li></ol><Link href="/economics" className="text-link">Review conditional economics <ChevronRight size={16}/></Link></Panel></div><Next slug="demand" label="Demand model" /></>;
}

function Demand() {
  const rows = planningCases.filter(row => row.mix === "planning_base" && ((row.year === "2027" && row.case === "base") || row.year === "2030" || (row.year === "2035" && (row.case === "base" || row.case === "high"))));
  const profiles = modelInputs.consortium_member_profiles;
  const taskRows = websiteData.primary_task_mix_outputs.filter(row => row.year === 2030 && row.case === "base");
  return <><ResearchNote/><Step2Note/><div className="flow">{["Members", "Primary tasks", "Reference GPU / CPU hours", "Three-tier equipment", "Facility MW"].map((item,i)=><div className="flow-step" key={item}><span>0{i+1}</span><strong>{item}</strong><small>{i===4?"Planning output":"Evidence + assumption"}</small></div>)}</div><div className="two-col"><Panel><SectionHead eyebrow="CONSORTIUM MIX · EXAMPLE ASSUMPTION" title="Five members, different demand strengths" note="Weights represent modeled demand relative to one MIT reference unit. They are not population ratios or measured consortium use."/><div className="model-rows">{profiles.map((profile,i)=><div key={profile.id}><span>{i===0?"Frontier research anchor":i<3?`Research-intensive member ${i}`:`Research + teaching member ${i-2}`}</span><strong>{profile.effective_demand_vs_mit_reference.toFixed(2)}×</strong></div>)}<div><span>Combined MIT reference demand units</span><strong>{modelInputs.consortium_mit_equivalents.toFixed(2)}</strong></div></div></Panel><Panel><SectionHead eyebrow="2030 BASE · PREFERRED PLANNING CASE" title="From task hours to three-tier MW" note="Physical L40S device-hours rise when work is shifted from high-end cards under assumed throughput factors; hours across tiers are not equivalent compute."/><div className="model-rows"><div><span>B200 device-hours / year</span><strong>{(Number(planningBase.b200_gpu_hours)/1e6).toFixed(2)}M</strong></div><div><span>H200 device-hours / year</span><strong>{(Number(planningBase.h200_gpu_hours)/1e6).toFixed(2)}M</strong></div><div><span>L40S-class device-hours / year</span><strong>{(Number(planningBase.l40s_gpu_hours)/1e6).toFixed(2)}M</strong></div><div><span>CPU-only core-hours / year</span><strong>{(Number(planningBase.cpu_core_hours)/1e6).toFixed(2)}M</strong></div><div><span>Facility design power</span><strong>{Number(planningBase.facility_design_mw).toFixed(2)} MW</strong></div></div></Panel></div><Panel><SectionHead eyebrow="EXCLUSIVE COMPUTE ACCOUNTING" title="Four primary tasks, two nonadditive labels" note="Original B200/H200 reference hours describe work before the assumed three-tier redistribution. Biomedical and robotics tags add no separate hours."/><Table><TableHeader><TableRow><TableHead>Primary task</TableHead><TableHead>Original reference tier</TableHead><TableHead>2030 base reference hours</TableHead><TableHead>Research status</TableHead></TableRow></TableHeader><TableBody>{taskRows.map(row=><TableRow key={row.primary_compute_task}><TableCell className="table-strong">{categoryLabels[row.primary_compute_task] || row.primary_compute_task}</TableCell><TableCell>{row.reference_device}</TableCell><TableCell>{(row.shared_reference_gpu_hours/1e6).toFixed(2)}M</TableCell><TableCell><Placeholder label="Assumption" /></TableCell></TableRow>)}</TableBody></Table><p className="source-small">Coding agents are an inference subtype with distinct incremental requests assumed. Real task IDs, performance and local/secure eligibility are needed to validate the split.</p></Panel><Panel><SectionHead eyebrow="2027–2035 CAPACITY STRESS TESTS" title="A 25 MW envelope covers the modeled base, not the high case" note="Preferred three-tier mix throughout; member weights, demand growth and GPU throughput remain assumptions."/><Table><TableHeader><TableRow><TableHead>Year / case</TableHead><TableHead>B200</TableHead><TableHead>H200</TableHead><TableHead>L40S-class</TableHead><TableHead>CPU-only cores</TableHead><TableHead>Facility MW</TableHead><TableHead>vs 25 MW</TableHead></TableRow></TableHeader><TableBody>{rows.map(row=><TableRow key={`${row.year}-${row.case}`}><TableCell className="table-strong">{row.year} · {row.case}</TableCell><TableCell>{Number(row.b200_gpu_count).toLocaleString()}</TableCell><TableCell>{Number(row.h200_gpu_count).toLocaleString()}</TableCell><TableCell>{Number(row.l40s_gpu_count).toLocaleString()}</TableCell><TableCell>{Number(row.cpu_only_cores).toLocaleString()}</TableCell><TableCell>{Number(row.facility_design_mw).toFixed(2)}</TableCell><TableCell>{Number(row.headroom_to_25mw)>=0?`${Number(row.headroom_to_25mw).toFixed(2)} headroom`:`${Math.abs(Number(row.headroom_to_25mw)).toFixed(2)} above`}</TableCell></TableRow>)}</TableBody></Table><p className="source-small">The confirmed 25 MW definition is total facility design input, not an approved connection. At assumed PUE {modelInputs.infrastructure.pue.toFixed(2)}, its IT planning capacity is about {(modelInputs.facility_target_mw/modelInputs.infrastructure.pue).toFixed(2)} MW; peak systems need engineering review. The 2035 high case needs eligible external capacity or another expansion path.</p></Panel><Next slug="architecture" label="Architecture" /></>;
}

function GpuTierAudit() {
  const order = ["scientific_ai_hpc", "fine_tuning_rl", "training", "inference"] as const;
  const fractions = planningInputs.tier_split_fraction_of_original_reference_work.planning_base;
  const factors = planningInputs.hours_per_original_reference_hour;
  return <Panel className="tier-audit"><SectionHead eyebrow="CURRENT PLANNING ASSUMPTION · NOT OBSERVED USE" title="Qualify B200, H200 and L40S by task" note="63.3% of original reference work is assigned to B200/H200 classes and 36.7% to L40S-class. MIT job counts indicate material mid-tier use but cannot establish GPU-hour shares."/><Table><TableHeader><TableRow><TableHead>Primary task</TableHead><TableHead>B200 work share</TableHead><TableHead>H200 work share</TableHead><TableHead>L40S work share</TableHead><TableHead>L40S hours / original hour</TableHead></TableRow></TableHeader><TableBody>{order.map(task=>{const row=fractions[task] as Record<string,number>;const hour=factors[task] as Record<string,number>;return <TableRow key={task}><TableCell className="table-strong">{categoryLabels[task]}</TableCell><TableCell>{((row.B200||0)*100).toFixed(0)}%</TableCell><TableCell>{((row.H200||0)*100).toFixed(0)}%</TableCell><TableCell>{((row.L40S||0)*100).toFixed(0)}%</TableCell><TableCell>{hour.L40S?`${hour.L40S.toFixed(1)}× assumed`:"—"}</TableCell></TableRow>})}</TableBody></Table><p className="source-small"><a href="https://orcd-docs.mit.edu/running-jobs/requesting-resources/" target="_blank" rel="noreferrer">MIT resource guidance</a> treats L40S as the default for many ML jobs and H200 as a higher-memory or FP64 choice. The device-hour conversion factors, mix and service fit still need representative project benchmarks. L40S uses 48 GB GDDR6 per card, not HBM. <a href="https://www.nvidia.com/en-us/data-center/l40s/" target="_blank" rel="noreferrer">NVIDIA L40S</a>.</p></Panel>;
}

function FacilityPowerBridge() {
  const pue = modelInputs.infrastructure.pue;
  const itCapacity = modelInputs.facility_target_mw / pue;
  return <Panel className="power-bridge"><SectionHead eyebrow="CONFIRMED DEFINITION · PLANNING ESTIMATE" title="Stage an expandable 25 MW facility envelope" note="The preferred 70% colo-core base case uses a modeled 12 MW first-phase facility commitment in 2030, followed by a conditional 15 MW step in 2033. Higher demand may require a larger first phase. PUE 1.20 is a provisional planning overhead factor, not an engineered peak, UPS or cooling rating."/><div className="metric-strip"><div><span>Expandable facility target</span><strong>25 MW</strong></div><div><span>Indicative IT limit</span><strong>{itCapacity.toFixed(2)} MW</strong></div><div><span>2030 base IT design</span><strong>{Number(planningBase.it_design_mw).toFixed(2)} MW</strong></div><div><span>2030 facility design</span><strong>{Number(planningBase.facility_design_mw).toFixed(2)} MW</strong></div><div><span>2035 base facility</span><strong>{Number(planningCases.find(row=>row.mix==="planning_base"&&row.year==="2035"&&row.case==="base")!.facility_design_mw).toFixed(2)} MW</strong></div></div><p className="source-small">2030 base has a chassis-only lower bound of {Number(planningBase.gpu_rack_lower_bound)} GPU racks. CPU, storage, network, power distribution, service clearance and cooling may raise the count. No parcel has a confirmed staged power offer. <a href="https://www.energy.gov/sites/default/files/2024-07/best-practice-guide-data-center-design.pdf" target="_blank" rel="noreferrer">US DOE data center design guide</a>.</p></Panel>;
}

function RequirementsMatrix() {
  const dimensions = [
    ["Security & data", "security_gate"],
    ["Latency", "latency_gate"],
    ["Data movement", "data_gravity_gate"],
    ["GPU selection", "gpu_freshness_gate"],
    ["Reliability", "reliability_gate"],
    ["Utilization", "utilization_gate"],
  ] as const;
  return <Panel className="requirements-matrix"><SectionHead eyebrow="CONDITIONAL REQUIREMENTS · POLICY REVIEW PENDING" title="Qualify each workload before placing it" note="These are questions to test, not approved consortium policy or service levels. Biomedical and robotics are nonadditive labels on primary tasks; coding agents are a subtype of inference."/><div className="requirements-grid">{requirementsData.rows.map(row=><article className="requirements-card" key={row.display_category}><div className="requirements-card-head"><h3>{categoryLabels[row.display_category]}</h3><span>{row.accounting_role.replaceAll("_", " ")}</span></div><dl>{dimensions.map(([label,key])=><div key={key}><dt>{label}</dt><dd>{row[key]}</dd></div>)}</dl><div className="requirements-geo">Planning geography <Placeholder label={row.display_category === "biomedical_private_ai" ? "Secure if approved" : row.display_category === "robotics" ? "Local control · US batch" : "US candidate · review"} /></div></article>)}</div><p className="source-small">Security and geography require each project's data owner, agreements, jurisdiction, access controls and service targets. <a href="https://orcd.mit.edu/resources/data-policies" target="_blank" rel="noreferrer">MIT ORCD's current general-system data policy</a> applies to that platform, not every university or the proposed consortium. <a href="https://www.grants.nih.gov/policy-and-compliance/policy-topics/sharing-policies/accessing-data/requirements" target="_blank" rel="noreferrer">NIH controlled-access requirements</a> require dataset-specific review. A US consortium-controlled center, owned or contractually dedicated, is a planning candidate for approved restricted work in an isolated secure zone and other permitted work in a general zone. Ownership or contract does not grant dataset access; unapproved data stay at origin. Cloud, dedicated colo, own and hybrid remain to be compared.</p></Panel>;
}

function Architecture() {
  const stack = [["Compute", "Three-tier GPU mix, CPU / GPU ratio and refresh cohorts"],["Data", "Storage tiers, throughput, retention and secure-zone separation"],["Connectivity", "Campus fiber, fabric and workload latency"],["Facility", "Rack density, hybrid cooling and provisional PUE"]];
  const mixRows = ["mid_tier_heavy","planning_base","high_end_heavy"].map(mix=>planningCases.find(row=>row.mix===mix&&row.year==="2030"&&row.case==="base")!);
  return <><ResearchNote/><Step2Note/><GpuTierAudit/><Panel className="architecture-summary"><SectionHead eyebrow="CURRENT THREE-TIER PLANNING BASE · 2030" title="Illustrative compute footprint" note="The same task workload is mapped to different device classes using unmeasured tier eligibility and throughput factors; no equipment purchase is approved."/><div className="metric-strip"><div><span>B200 GPUs</span><strong>{Number(planningBase.b200_gpu_count).toLocaleString()}</strong></div><div><span>H200 GPUs</span><strong>{Number(planningBase.h200_gpu_count).toLocaleString()}</strong></div><div><span>L40S-class GPUs</span><strong>{Number(planningBase.l40s_gpu_count).toLocaleString()}</strong></div><div><span>CPU-only cores</span><strong>{Number(planningBase.cpu_only_cores).toLocaleString()}</strong></div><div><span>IT design</span><strong>{Number(planningBase.it_design_mw).toFixed(2)} MW</strong></div><div><span>Facility design</span><strong>{Number(planningBase.facility_design_mw).toFixed(2)} MW</strong></div></div><p className="source-small">B200 and H200 reference chassis: <a href="https://docs.nvidia.com/dgx/dgxb200-user-guide/introduction-to-dgxb200.html" target="_blank" rel="noreferrer">DGX B200</a> and <a href="https://docs.nvidia.com/dgx/dgxh100-user-guide/introduction-to-dgxh100.html" target="_blank" rel="noreferrer">DGX H200</a>. Four-L40S node design power of 2.8 kW is a planning assumption; liquid or hybrid cooling, fabric and storage need engineering design.</p></Panel><FacilityPowerBridge/><Panel className="technology-panel"><SectionHead eyebrow="DEVICE MIX SENSITIVITY · ASSUMPTIONS ONLY" title="Three tier choices change both fleet and MW" note="High-end share is the fraction of original reference work assigned to B200/H200, not the share of physical GPU-hours after throughput conversion."/><Table><TableHeader><TableRow><TableHead>2030 base mix</TableHead><TableHead>High-end work share</TableHead><TableHead>B200 / H200 / L40S GPUs</TableHead><TableHead>Facility design MW</TableHead></TableRow></TableHeader><TableBody>{mixRows.map(row=><TableRow key={row.mix}><TableCell className="table-strong">{mixLabels[row.mix]}</TableCell><TableCell>{(Number(row.high_end_share_of_original_reference_work)*100).toFixed(1)}%</TableCell><TableCell>{Number(row.b200_gpu_count).toLocaleString()} / {Number(row.h200_gpu_count).toLocaleString()} / {Number(row.l40s_gpu_count).toLocaleString()}</TableCell><TableCell>{Number(row.facility_design_mw).toFixed(2)} MW</TableCell></TableRow>)}</TableBody></Table><p className="source-small">Across these three mixes, 2030 facility design ranges from 12.93 to 13.54 MW. Reference performance and throughput are held fixed; actual hardware generations and task benchmarks can change both cost and power.</p></Panel><div className="four-grid">{stack.map(([a,b],i)=><Panel key={a} className="stack-card"><span>0{i+1}</span><h3>{a}</h3><p>{b}</p><Placeholder label="Design TBD" /></Panel>)}</div><RequirementsMatrix/><Panel className="thin-panel"><strong>Historical stress reference</strong><span>The earlier all-B200/H200 model estimated {legacyBase.facility_design_mw.toFixed(2)} MW for 2030 base. It remains a high-end-heavy comparison, separate from the current three-tier planning recommendation and its economics.</span></Panel><Next slug="location" label="Location" /></>;
}

function SiteScreening() {
  const names: Record<string,string> = { TX_ERCOT:"Texas · ERCOT service area", IA_MISO:"Iowa · MISO service area", OH_AEP_PJM:"Central Ohio · AEP / PJM", VA_DOM_PJM:"Virginia · Dominion / PJM" };
  const regions = [...candidateRegions.rows].sort((a,b) => names[a.region_id].localeCompare(names[b.region_id]));
  return <><Panel className="site-screening"><SectionHead eyebrow="STEP 6 · INQUIRY POOL, NOT A RANKING" title="Four US regions for written utility and site inquiries" note="These are broad service-area screens, not named parcels or confirmed sites. No region has a verified 25 MW connection, energization date or data-center tariff."/><Table><TableHeader><TableRow><TableHead>Unranked inquiry region</TableHead><TableHead>2024 state industrial average</TableHead><TableHead>Parcel 25 MW supply</TableHead><TableHead>Energization date</TableHead></TableRow></TableHeader><TableBody>{regions.map(row=><TableRow key={row.region_id}><TableCell className="table-strong">{names[row.region_id]}</TableCell><TableCell>{Number(row.state_industrial_retail_cents_per_kwh).toFixed(2)} ¢/kWh</TableCell><TableCell><Placeholder label="Unknown" /></TableCell><TableCell><Placeholder label="Unknown" /></TableCell></TableRow>)}</TableBody></Table><p className="source-small">The price column is the <a href="https://www.eia.gov/electricity/sales_revenue_price/pdf/table_4.pdf" target="_blank" rel="noreferrer">EIA 2024 full-year state industrial retail average</a>, published in 2025. It is background context, not a current data-center quote, a 2030 forecast or a basis for ranking. Ask utilities for a named parcel, staged total-facility load ramp toward 25 MW, applicable charges, connection upgrades and dated service commitments before scoring any location.</p></Panel><details className="site-diligence"><summary>Written diligence requests · {siteDueDiligence.rows.length} open gates</summary><div>{siteDueDiligence.rows.map(row=><article key={row.gate_id}><strong>{row.dimension.replaceAll("_", " ")}</strong><span>{row.requested_evidence}</span><Placeholder label="Not requested" /></article>)}</div></details></>;
}

function Location() {
  const criteria = ["Power availability", "Time to power", "Fiber & latency", "Cooling / climate", "Permitting", "Climate & operational risk"];
  const ruleLabels: Record<string,string> = { LOCAL_CLOSED_LOOP:"Closed-loop control", RESTRICTED_APPROVED:"Approved restricted data", RESTRICTED_NOT_APPROVED:"Transfer not approved", US_SHARED_BATCH:"Permitted batch work", US_SHARED_INTERACTIVE:"Permitted interactive work" };
  const ruleStatus: Record<string,string> = { device_or_campus:"Device / campus", origin_institution:"Origin institution", us_consortium_controlled_secure_enclave:"Secure zone candidate", us_consortium_controlled_general_compute:"General zone candidate" };
  return <><ResearchNote/><Panel className="location-scope"><SectionHead eyebrow="USER-SELECTED PLANNING ASSUMPTION" title="Test a US consortium-controlled center with project-level access gates" note="The geographic screening case is a US center with general compute and a possible isolated secure environment under consortium control, owned or contractually dedicated. Final ownership remains open; on-site closed-loop control and datasets without transfer approval stay at the device or originating institution."/><div className="location-paths location-paths-three"><div><span>01 / DEVICE OR ORIGIN</span><h3>Keep near the source</h3><p>Robot and instrument closed-loop control; restricted datasets whose terms do not permit transfer or processing at the center.</p><small>Check control timing, failure behavior, dataset terms and the responsible institution.</small></div><div><span>02 / US CONTROLLED ENVIRONMENT</span><h3>Secure zone candidate</h3><p>Restricted human genomic or clinical compute only when the specific dataset, users and responsible institution are approved for this environment.</p><small>Confirm agreements, isolation, audit, access controls and any inter-institution service terms.</small></div><div><span>03 / US SHARED COMPUTE</span><h3>General zone candidate</h3><p>Permitted training, fine-tuning, scientific batch work, inference, coding agents and robot training or simulation.</p><small>Confirm project permission, transfer time, latency, availability and equipment fit.</small></div></div><p className="source-small">Owning or contracting a center does not grant data access or approve any specific dataset. Restricted work may qualify for an approved isolated environment after project-level review; it is not automatically excluded from center power demand. The US-only site search is a project scope choice, not a claim that public data must legally remain in the US. <a href="https://grants.nih.gov/policy-and-compliance/policy-topics/sharing-policies/accessing-data/using-genomic-data" target="_blank" rel="noreferrer">NIH guidance on third-party systems</a> · <a href="https://www.hhs.gov/hipaa/for-professionals/special-topics/health-information-technology/cloud-computing/index.html" target="_blank" rel="noreferrer">HHS HIPAA cloud guidance</a>.</p></Panel><Panel className="location-rules"><SectionHead eyebrow="ELIGIBILITY DECISION TREE" title="Approve the workload before scoring a city" note="Five conditional rules separate physical proximity from data permission. None records approval for a real dataset."/><div className="location-rule-grid">{eligibilityRules.rows.map((rule,i)=><div key={rule.rule_id}><span>0{i+1}</span><strong>{ruleLabels[rule.rule_id]}</strong><p>{rule.workload_component}</p><small>{rule.validation_needed}</small><Placeholder label={ruleStatus[rule.planning_location]}/></div>)}</div></Panel><Panel className="thin-panel"><strong>Demand model boundary</strong><span>The current three-tier 2030 planning base is {Number(planningBase.facility_design_mw).toFixed(2)} MW of facility design power; the base 70% colo-core inquiry is 12 MW in 2030 with a conditional 15 MW step in 2033; higher demand may require roughly 15 MW first. Project-level permissions and hours are unavailable, so no location-based MW adjustment has been made. Approved restricted work could run in a secure zone if that option is selected and qualified; unapproved work and closed-loop control remain at origin. The estimate is not validated transferable demand.</span></Panel><SiteScreening/><Panel><SectionHead eyebrow="US SITE SCORING FRAMEWORK" title="Evidence before a ranked shortlist" note="Only parcels that pass written power, network, cooling, permitting and workload-permission gates will be scored. Weights and thresholds remain TBD."/><div className="model-rows">{criteria.map(x=><div key={x}><span>{x}</span><Placeholder label="Weight TBD" /></div>)}</div></Panel><Next slug="economics" label="Economics" /></>;
}

function PhasedCapacityPanel() {
  const current = decisionData.planning_revision;
  const base = current.phased_underwriting_summary.find(row=>row.case==="base")!;
  const low = current.phased_underwriting_summary.find(row=>row.case==="low")!;
  const lowResizable = current.sensitivities.find(row=>row.variation==="demand_low_resized"&&row.option==="hybrid_colo")!;
  const cashflow = ["2030","2033","2036"].map(year=>current.phased_underwriting_cashflows.find(row=>row.case==="base"&&row.year===year)!);
  const bn = (value:string) => `$${(Number(value)/1e9).toFixed(3)}bn`;
  return <Panel className="phased-capacity"><SectionHead eyebrow="BASE-CASE STAGED UNDERWRITING · UNQUOTED" title="Commit 12 MW, then conditionally 15 MW" note="From 2030, 70% of each task category's annual hours are assigned to the controlled colo core and 30% to eligible cloud. The model has no hourly load curve; this cloud share is not a measured peak. 2027–2029 use cloud as a transition."/><Table><TableHeader><TableRow><TableHead>Year</TableHead><TableHead>Modeled committed facility input</TableHead><TableHead>Base on-site design load</TableHead><TableHead>Spare design capacity</TableHead></TableRow></TableHeader><TableBody>{cashflow.map(row=><TableRow key={row.year}><TableCell className="table-strong">{row.year}</TableCell><TableCell>{Number(row.committed_facility_mw).toFixed(0)} MW</TableCell><TableCell>{(Number(row.committed_facility_mw)-Number(row.spare_facility_mw)).toFixed(2)} MW</TableCell><TableCell>{Number(row.spare_facility_mw).toFixed(2)} MW</TableCell></TableRow>)}</TableBody></Table><div className="model-rows"><div><span>Base · locked 12 → 15 MW · 2027–2036 cost NPV</span><strong>{bn(base.cost_npv_usd)}</strong></div><div><span>Low demand · capacity already locked</span><strong>{bn(low.cost_npv_usd)}</strong></div><div><span>Low demand · resize allowed in model</span><strong>{bn(lowResizable.cost_npv_usd)}</strong></div></div><p className="source-small">The base staged case is about $14.8m NPV above a flexible capacity proxy. Locking capacity under low demand adds about $63.8m NPV against timely resizing. These are cost-only scenarios in constant 2026 dollars; no supplier has offered or reserved 12, 15, or 25 MW. A later 20–25 MW step is an option, not a modeled commitment.</p></Panel>;
}

