function Economics() {
  const current = decisionData.planning_revision;
  const names: Record<string,string> = { cloud:"Public-anchor all cloud", hybrid_colo:"70% controlled colo core + cloud", colo:"Full colo + consortium GPUs", hybrid_own:"70% owned core + cloud", own:"Full own build + GPUs", hybrid_dedicated:"70% dedicated rental + cloud", dedicated:"Full dedicated reservation" };
  const order = ["cloud","hybrid_colo","colo","hybrid_own","own","hybrid_dedicated","dedicated"];
  const options = order.map(id=>current.financial_options.find(row=>row.option===id&&row.mix==="planning_base"&&row.demand_case==="base")!);
  const stagedBase = current.phased_underwriting_summary.find(row=>row.case==="base")!;
  const stagedLow = current.phased_underwriting_summary.find(row=>row.case==="low")!;
  const bn = (value: string) => `$${(Number(value)/1e9).toFixed(3)}bn`;
  const variation = (id:string, option:string) => current.sensitivities.find(row=>row.variation===id&&row.option===option)!;
  const priceRows = ["B200","H200","L40S"] as const;
  return <><ResearchNote/><Panel className="finance-lead"><SectionHead eyebrow="CURRENT PREFERRED THREE-TIER MODEL · 2027–2036" title="Controlled colo core and cloud are close on modeled cost" note="From 2030, the illustrative 70% colo / 30% eligible cloud split allocates each task category’s annual hours. It is not a measured hourly peak profile. The staged 12 → 15 MW colo commitment and all-cloud comparison require matched quotes and site evidence."/><p>With 12 MW committed in 2030 and 15 MW in 2033, the modeled colo + eligible cloud share costs {bn(stagedBase.cost_npv_usd)} NPV. The flexible capacity proxy is {bn(options[1].cost_npv_usd)}; all cloud is {bn(options[0].cost_npv_usd)}. The roughly $40m gap between staged colo and all-cloud public anchors is too small to settle delivery without comparable bids, security terms and power dates.</p></Panel><PhasedCapacityPanel/><Panel className="financial-results"><SectionHead eyebrow="SEVEN OPTIONS · UNQUOTED MODEL ASSUMPTIONS" title="Ten-year costs on the current planning basis" note="NPV uses constant 2026 dollars and an assumed 8% real discount rate. Cloud anchors combine products from different providers; dedicated reservation rates and construction inputs are assumptions."/><Table><TableHeader><TableRow><TableHead>Delivery model</TableHead><TableHead>10-year TCO</TableHead><TableHead>Cost NPV</TableHead><TableHead>Evidence status</TableHead></TableRow></TableHeader><TableBody>{options.map(row=><TableRow key={row.option}><TableCell className="table-strong">{names[row.option]}</TableCell><TableCell>{bn(row.tco_usd)}</TableCell><TableCell>{bn(row.cost_npv_usd)}</TableCell><TableCell><Placeholder label="Planning model · no unified quote" /></TableCell></TableRow>)}</TableBody></Table><p className="source-small">The seven rows assume capacity can track actual annual use; the separate staged case locks 12 MW then 15 MW. The modeled public cloud prices are not one supplier's networked, secure, long-term offer. The $6.65/$3.45/$0.90 dedicated GPU-hour rates are assumed discounts on reserved hours, not quotes. Actual use, service obligations, secure-zone eligibility and startup dates may reverse the order. The older all-high-end AWS case remains a separate stress comparison.</p></Panel><div className="two-col"><Panel><SectionHead eyebrow="PUBLIC PRICE ANCHORS · DIFFERENT PRODUCTS" title="B200, H200 and L40S-class reference prices" note="Published examples anchor the scale; they do not establish a unified GPU fleet, equivalent fabric, security or capacity commitment."/><Table><TableHeader><TableRow><TableHead>Tier</TableHead><TableHead>Public $/GPU-hour</TableHead><TableHead>Assumed dedicated reserved</TableHead></TableRow></TableHeader><TableBody>{priceRows.map(tier=><TableRow key={tier}><TableCell className="table-strong">{tier}</TableCell><TableCell>${planningInputs.cloud_hourly_public_anchor[tier].toFixed(2)}</TableCell><TableCell>${planningInputs.dedicated_reserved_hourly_assumption[tier].toFixed(2)} · unquoted</TableCell></TableRow>)}</TableBody></Table><p className="source-small">B200: <a href="https://lambda.ai/pricing" target="_blank" rel="noreferrer">Lambda 256+ GPU cluster</a>; H200 multi-node and L40S Secure Cloud: <a href="https://www.runpod.io/articles/guides/ai-server-cost" target="_blank" rel="noreferrer">Runpod published examples</a>. Direct $/GPU-hour and break-even utilization cannot be treated as a full TCO comparison across these products; benchmark the same tasks and service levels.</p></Panel><Panel><SectionHead eyebrow="DECISION SENSITIVITY" title="Small changes matter" note="Each result changes one assumption in the current three-tier model; none is a forecast."/><div className="model-rows"><div><span>Cloud price +50% · all-cloud NPV</span><strong>{bn(variation("cloud_price_plus_50pct","cloud").cost_npv_usd)}</strong></div><div><span>GPU refresh every 3 years · 70% colo core</span><strong>{bn(variation("gpu_refresh_3_years","hybrid_colo").cost_npv_usd)}</strong></div><div><span>First-phase online 2032 · full own</span><strong>{bn(variation("facility_online_2032","own").cost_npv_usd)}</strong></div><div><span>25% lower utilization · 70% colo core</span><strong>{bn(variation("utilization_25pct_lower","hybrid_colo").cost_npv_usd)}</strong></div></div><p className="source-small">The 12 MW 2030 and conditional 15 MW 2033 steps are assumed facility-input commitments for the 70% colo core. A 20–25 MW third step remains an uncommitted option. No parcel has a committed utility date or approved capital budget.</p></Panel></div><Next slug="risk-delivery" label="Risk & Delivery" /></>;
}

function RiskDelivery() {
  const risks = decisionData.planning_revision.risk_register;
  const riskNames: Record<string,string> = { PRICE_COMPARABILITY:"Public prices differ by product", GPU_TIER:"GPU tier and throughput", GPU_REFRESH:"Refresh cycle", UTILIZATION:"Core capacity underuse", POWER_DELAY:"First-phase power delay", DEDICATED_PRICE:"Dedicated reservation rate", BUILD_COST:"Facility build cost", POWER_PRICE:"Power price", DATA_PERMISSION:"Restricted-data approval", PERMIT_COOLING:"Permitting and cooling", FIBER_RELIABILITY:"Fiber and reliability" };
  const phaseNames: Record<string,string> = { DISCOVERY:"2026 Q4–2027 H1", PROCUREMENT:"2027 H2–2028", DESIGN_BUILD:"2028–2029", FIRST_PHASE:"2030 · conditional", EXPANSION_REFRESH:"2031–2036" };
  const bn = (value:string) => `$${(Number(value)/1e9).toFixed(3)}bn`;
  const base = decisionData.planning_revision.financial_options.find(row=>row.option==="hybrid_colo"&&row.mix==="planning_base"&&row.demand_case==="base")!;
  const delayed = decisionData.planning_revision.sensitivities.find(row=>row.variation==="facility_online_2032"&&row.option==="hybrid_colo")!;
  const stagedLow = decisionData.planning_revision.phased_underwriting_summary.find(row=>row.case==="low")!;
  return <><ResearchNote/><Panel><SectionHead eyebrow="CURRENT PLANNING RISK REGISTER" title="Price comparability, GPU fit and power lead the gates" note="Risk levels are research judgments, not observed probabilities. Model impacts change one assumption at a time and exclude penalties."/><div className="risk-summary">{risks.map(row=><div key={row.risk_id}><strong>{riskNames[row.risk_id]}</strong><span>{row.level.replaceAll("_"," ")}</span><small>{row.decision_gate}</small></div>)}</div><p className="source-small">The flexible-capacity proxy moves from {bn(base.cost_npv_usd)} to {bn(delayed.cost_npv_usd)} with a two-year first-phase delay. In the separate locked 12 → 15 MW low-demand case, NPV is {bn(stagedLow.cost_npv_usd)}, about $63.8m above a contract that can resize promptly. Security and parcel eligibility cannot yet be assigned MW or a probability.</p></Panel><Panel><SectionHead eyebrow="STAGED DELIVERY · BASE CASE ONLY" title="Cloud transition, then conditional facility commitments" note="Capacity figures are total facility input, not IT load or secured utility capacity."/><div className="timeline"><div><strong>2027–2029 · cloud transition</strong><span>Measure member queues, approve eligible data paths, benchmark GPU tiers and seek comparable service terms.</span><Placeholder label="Evidence gate"/></div><div><strong>2030 · modeled 12 MW</strong><span>Open a controlled colo core only if written power, security, price and exit terms support the 9.26 MW base on-site load.</span><Placeholder label="Conditional"/></div><div><strong>2033 · modeled 15 MW</strong><span>Expand if observed use supports it. Keep 20–25 MW as an uncommitted later option; high demand needs eligible off-site capacity.</span><Placeholder label="Conditional"/></div></div><p className="source-small">The 12 → 15 MW ladder applies to the base 70% annual-hours colo allocation. Low demand supports delay or downsizing; high demand may need roughly 15 MW at the first phase. No stage has a supplier quote or approval.</p></Panel><Panel className="timeline-panel"><SectionHead eyebrow="PROVISIONAL ROADMAP" title="Cloud transition first; 12 → 15 MW only if gates pass" note="The modeled 2030 12 MW and 2033 15 MW facility-input steps require written power, service and exit terms. The 25 MW envelope stays uncommitted. No utility energization or campus migration is guaranteed."/><div className="timeline-list">{decisionData.timeline.map(row=><div key={row.phase_id}><strong>{phaseNames[row.phase_id]}</strong><span>{row.work}</span><small>{row.gate}</small><Placeholder label={row.phase_id==="FIRST_PHASE"?"Conditional target":"Provisional"}/></div>)}</div></Panel><Next slug="scenario-lab" label="Scenario Lab" /></>;
}

const initialInputs = {
  memberAnchor: String(modelInputs.consortium_member_profiles[0].effective_demand_vs_mit_reference),
  memberResearchA: String(modelInputs.consortium_member_profiles[1].effective_demand_vs_mit_reference),
  memberResearchB: String(modelInputs.consortium_member_profiles[2].effective_demand_vs_mit_reference),
  memberMixedA: String(modelInputs.consortium_member_profiles[3].effective_demand_vs_mit_reference),
  memberMixedB: String(modelInputs.consortium_member_profiles[4].effective_demand_vs_mit_reference),
  demandMultiplier: String(modelInputs.scenarios.find(item => item.year === 2030 && item.case === "base")!.demand_multiplier),
  b200Utilization: String(modelInputs.hardware_reference.B200.schedulable_utilization * 100),
  h200Utilization: String(modelInputs.hardware_reference.H200.schedulable_utilization * 100),
  l40sUtilization: String(planningInputs.l40s_reference.schedulable_utilization * 100),
  pue: String(modelInputs.infrastructure.pue),
  tierMix: "planning_base",
};
type ScenarioInputs = typeof initialInputs;
type SavedScenario = { id: string; name: string; updatedAt?: string };
const memberKeys = ["memberAnchor", "memberResearchA", "memberResearchB", "memberMixedA", "memberMixedB"] as const;
function parsedScenario(input: ScenarioInputs) {
  if (!input || memberKeys.some(key => input[key] === undefined)) return null;
  const memberWeights = memberKeys.map(key => Number(input[key]));
  const values = { memberWeights, demandMultiplier:Number(input.demandMultiplier), b200Utilization:Number(input.b200Utilization)/100, h200Utilization:Number(input.h200Utilization)/100, l40sUtilization:Number(input.l40sUtilization)/100, pue:Number(input.pue), tierMix:input.tierMix as "mid_tier_heavy" | "planning_base" | "high_end_heavy" };
  if (!memberWeights.every(weight => Number.isFinite(weight) && weight >= 0 && weight <= 2) || memberWeights.reduce((sum,weight)=>sum+weight,0)<=0 || !Number.isFinite(values.demandMultiplier) || values.demandMultiplier<=0 || values.demandMultiplier>10 || [values.b200Utilization,values.h200Utilization,values.l40sUtilization].some(value=>!Number.isFinite(value)||value<=0||value>0.95) || !Number.isFinite(values.pue) || values.pue<1 || values.pue>3 || !mixLabels[values.tierMix]) return null;
  return {...calculatePlanning(values), coreFacilityMw:calculatePlanning({...values,demandMultiplier:values.demandMultiplier*0.7}).facilityMw};
}
function FinancialSensitivityLab() {
  const cases = [["base","Current planning base"],["demand_low_resized","Low demand · resize allowed"],["demand_high_with_25mw_cap","High demand · 25 MW cap"],["mid_tier_heavy","More mid-tier GPUs"],["high_end_heavy","More high-end GPUs"],["cloud_price_plus_50pct","Cloud price +50%"],["cloud_price_minus_20pct","Cloud price −20%"],["dedicated_rate_minus_25pct","Dedicated rate −25%"],["facility_online_2032","Center online 2032"],["gpu_refresh_3_years","Three-year GPU refresh"],["gpu_refresh_5_years","Five-year GPU refresh"],["utilization_25pct_lower","Utilization −25%"],["power_price_0.12","Power $0.12/kWh"],["facility_capex_14m_per_it_mw","Facility $14m/IT MW"]] as const;
  const [selectedCase,setSelectedCase] = useState<string>("base");
  const current = decisionData.planning_revision;
  const names:Record<string,string> = { cloud:"Public-anchor cloud",hybrid_colo:"70% colo core + cloud",colo:"Full colo",hybrid_own:"70% own core + cloud",own:"Full own",hybrid_dedicated:"70% dedicated + cloud",dedicated:"Full dedicated" };
  const rows = ["cloud","hybrid_colo","colo","hybrid_own","own","hybrid_dedicated","dedicated"].map(option=>selectedCase==="base"?current.financial_options.find(row=>row.option===option&&row.mix==="planning_base"&&row.demand_case==="base")!:current.sensitivities.find(row=>row.variation===selectedCase&&row.option===option)!);
  return <Panel className="finance-sensitivity-lab"><SectionHead eyebrow="SEPARATE PRECOMPUTED FINANCIAL CASES" title="Explore price, delivery, refresh and tier mix" note="These stored cases use unquoted assumptions and cross-product public price anchors. The low-demand sensitivity assumes timely resizing; high demand caps the site at 25 MW and routes eligible remainder elsewhere. They are independent from the editable demand and PUE inputs above."/><label className="field"><span>Financial model case</span><select value={selectedCase} onChange={event=>setSelectedCase(event.target.value)}>{cases.map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><Table><TableHeader><TableRow><TableHead>Option</TableHead><TableHead>Cost NPV · assumption</TableHead><TableHead>10-year TCO · assumption</TableHead></TableRow></TableHeader><TableBody>{rows.map(row=><TableRow key={row.option}><TableCell className="table-strong">{names[row.option]}</TableCell><TableCell>${(Number(row.cost_npv_usd)/1e9).toFixed(3)}bn</TableCell><TableCell>${(Number(row.tco_usd)/1e9).toFixed(3)}bn</TableCell></TableRow>)}</TableBody></Table><p className="source-small">A selected financial case is not saved with the demand scenario above. The 12 → 15 MW locked-capacity case is shown separately; these sensitivity rows do not include its underuse penalty. Model results do not imply the products are identical or deliverable to one parcel.</p></Panel>;
}
function ScenarioLab() {
  const [inputs,setInputs] = useState<ScenarioInputs>(initialInputs);
  const [name,setName] = useState("2030 three-tier planning base · illustrative");
  const [message,setMessage] = useState("");
  const [saved,setSaved] = useState<SavedScenario[]>([]);
  const [selected,setSelected] = useState("");
  const [compared,setCompared] = useState<{name:string;facilityMw:number}|null>(null);
  useEffect(()=>{
    type ToolContext = {registerTool:(tool:{name:string;title:string;description:string;inputSchema:object;annotations:object;execute:(input:unknown)=>unknown},options:{signal:AbortSignal})=>void|Promise<void>};
    const context=(document as Document & {modelContext?:ToolContext}).modelContext;
    if(!context?.registerTool)return;
    const controller=new AbortController();
    const tool={name:"set_scenario_assumptions",title:"Set scenario assumptions",description:"Stage member weights, a demand multiplier, three GPU utilizations, PUE and one tier mix in Scenario Lab.",inputSchema:{type:"object",properties:{memberWeights:{type:"array",minItems:5,maxItems:5,items:{type:"number",minimum:0,maximum:2}},demandMultiplier:{type:"number",exclusiveMinimum:0,maximum:10},b200Utilization:{type:"number",exclusiveMinimum:0,maximum:95},h200Utilization:{type:"number",exclusiveMinimum:0,maximum:95},l40sUtilization:{type:"number",exclusiveMinimum:0,maximum:95},pue:{type:"number",minimum:1,maximum:3},tierMix:{type:"string",enum:["mid_tier_heavy","planning_base","high_end_heavy"]}},required:["memberWeights","demandMultiplier","b200Utilization","h200Utilization","l40sUtilization","pue","tierMix"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input:unknown)=>{const item=input as Record<string,unknown>;if(!Array.isArray(item.memberWeights)||item.memberWeights.length!==5)throw new Error("Provide five member weights.");const next={memberAnchor:String(item.memberWeights[0]),memberResearchA:String(item.memberWeights[1]),memberResearchB:String(item.memberWeights[2]),memberMixedA:String(item.memberWeights[3]),memberMixedB:String(item.memberWeights[4]),demandMultiplier:String(item.demandMultiplier),b200Utilization:String(item.b200Utilization),h200Utilization:String(item.h200Utilization),l40sUtilization:String(item.l40sUtilization),pue:String(item.pue),tierMix:String(item.tierMix)};const output=parsedScenario(next);if(!output)throw new Error("Invalid planning assumptions.");setInputs(next);setMessage("Illustrative assumptions updated.");return {status:"staged",effectiveDemandUnits:Number(output.effectiveDemandUnits.toFixed(2)),facilityDesignMw:Number(output.facilityMw.toFixed(2)),asOf:websiteData.as_of,classification:"planning assumption"};}};
    try{void Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}
    return()=>controller.abort();
  },[]);
  const result=parsedScenario(inputs);
  const memberFields=[["memberAnchor","Frontier research anchor"],["memberResearchA","Research-intensive member A"],["memberResearchB","Research-intensive member B"],["memberMixedA","Research + teaching member A"],["memberMixedB","Research + teaching member B"]] as const;
  const modelFields=[["demandMultiplier","Demand vs 2027 base","×"],["b200Utilization","B200 schedulable utilization","%"],["h200Utilization","H200 schedulable utilization","%"],["l40sUtilization","L40S schedulable utilization","%"],["pue","Facility PUE","ratio"]] as const;
  async function refreshSaved(){try{const response=await fetch("/api/scenarios");const data=await response.json() as {error?:string;scenarios?:SavedScenario[]};if(!response.ok)throw new Error(data.error);setSaved(data.scenarios||[]);setMessage((data.scenarios||[]).length?"Choose a saved scenario to load or compare.":"No saved scenarios yet.");}catch(error){setMessage(error instanceof Error?error.message:"Saved scenarios are unavailable.");}}
  async function save(){if(!result){setMessage("Check all inputs before saving.");return;}try{const response=await fetch("/api/scenarios",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name,inputs})});const data=await response.json() as {error?:string;scenario?:SavedScenario};if(!response.ok)throw new Error(data.error);setMessage("Scenario saved.");await refreshSaved();if(data.scenario)setSelected(data.scenario.id);}catch(error){setMessage(error instanceof Error?error.message:"Scenario could not be saved.");}}
  async function retrieve(compare:boolean){if(!selected){await refreshSaved();return;}try{const response=await fetch(`/api/scenarios/${encodeURIComponent(selected)}`);const data=await response.json() as {error?:string;scenario?:{name:string;inputs:ScenarioInputs}};if(!response.ok)throw new Error(data.error);const loaded=data.scenario;if(!loaded)throw new Error("Scenario not found.");const output=parsedScenario(loaded.inputs);if(!output)throw new Error("This saved scenario uses an earlier model. Recreate it with a three-tier mix.");if(compare){setCompared({name:loaded.name,facilityMw:output.facilityMw});setMessage("Comparing facility design power only; financial cases are separate.");}else{setInputs(loaded.inputs);setName(loaded.name);setCompared(null);setMessage("Scenario loaded.");}}catch(error){setMessage(error instanceof Error?error.message:"Scenario could not be loaded.");}}
  return <><ResearchNote/><Step2Note/><div className="two-col scenario-layout"><Panel><SectionHead eyebrow="CURRENT THREE-TIER PLANNING INPUTS" title="Test member scale, tier mix and power" note="Five hypothetical weights total 3.5 MIT reference units in the base case. Edit them to stress-test scale; the result is not observed use or an engineered load sheet."/><label className="field"><span>Scenario name</span><input value={name} onChange={e=>setName(e.target.value)} placeholder="Scenario name" /></label><div className="scenario-subhead">Member demand weights · example assumptions</div><div className="input-grid">{memberFields.map(([key,label])=><label className="field" key={key}><span>{label}</span><div className="input-wrap"><input type="number" min="0" max="2" step="any" value={inputs[key]} onChange={e=>setInputs({...inputs,[key]:e.target.value})}/><small>× MIT ref</small></div></label>)}</div><p className="effective-units">Combined effective demand: <strong>{result?result.effectiveDemandUnits.toFixed(2):"Check inputs"} MIT reference units</strong></p><div className="scenario-subhead">Demand and facility assumptions</div><div className="input-grid">{modelFields.map(([key,label,unit])=><label className="field" key={key}><span>{label}</span><div className="input-wrap"><input type="number" step="any" value={inputs[key]} onChange={e=>setInputs({...inputs,[key]:e.target.value})}/><small>{unit}</small></div></label>)}</div><div className="scenario-subhead">Task-to-GPU tier mix</div><label className="field"><span>Planning mix</span><select value={inputs.tierMix} onChange={e=>setInputs({...inputs,tierMix:e.target.value})}>{Object.entries(mixLabels).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><p className="source-small">Tier shares and L40S/H200 throughput factors are assumptions from the current planning revision. PUE is a facility-power planning proxy. No result includes a project-level secure-zone or campus-origin split.</p><div className="scenario-actions"><button onClick={save}>Save scenario</button><button className="secondary-button" onClick={()=>retrieve(false)}>Load selected</button><button className="secondary-button" onClick={()=>retrieve(true)}>Compare</button></div>{message&&<p className="inline-note" role="status">{message}</p>}</Panel><div className="scenario-results"><Panel className="dark-panel"><div className="eyebrow">PLANNING ASSUMPTION · AS OF {websiteData.as_of}</div><h2>{name||"Untitled scenario"}</h2><p>This interactive model maps mutually exclusive primary tasks to B200, H200 and L40S classes. Biomedical and robotics remain nonadditive labels. Counts and power are illustrative, with no verified site, service quote or data permission.</p><div className="scenario-result-rows"><div><span>Effective demand units</span><strong>{result?result.effectiveDemandUnits.toFixed(2):"Check inputs"}</strong></div><div><span>High-end share of original work</span><strong>{result?`${(result.highEndOriginalShare*100).toFixed(1)}%`:"TBD"}</strong></div><div><span>B200 / H200 / L40S GPUs</span><strong>{result?`${result.b200Count.toLocaleString()} / ${result.h200Count.toLocaleString()} / ${result.l40sCount.toLocaleString()}`:"TBD"}</strong></div><div><span>IT design power</span><strong>{result?`${result.itMw.toFixed(2)} MW`:"Check inputs"}</strong></div><div><span>Full-workload facility design power</span><strong>{result?`${result.facilityMw.toFixed(2)} MW`:"Check inputs"}</strong></div><div><span>70% annual-hours colo core · proxy</span><strong>{result?`${result.coreFacilityMw.toFixed(2)} MW`:"Check inputs"}</strong></div><div><span>Indicative IT capacity at selected PUE</span><strong>{result?`${result.itCapacityMw.toFixed(2)} MW`:"TBD"}</strong></div><div><span>Headroom vs 25 MW planning ceiling</span><strong>{result?`${result.headroomMw.toFixed(2)} MW`:"TBD"}</strong></div><div><span>General / secure / origin load split</span><strong>TBD</strong></div></div>{compared&&<div className="comparison"><span>COMPARE WITH {compared.name}</span><strong>{compared.facilityMw.toFixed(2)} MW</strong><small>{result?`${(result.facilityMw-compared.facilityMw).toFixed(2)} MW difference`:""}</small></div>}</Panel><Panel><div className="eyebrow">SAVED SCENARIOS</div><div className="saved-controls"><select value={selected} onChange={e=>setSelected(e.target.value)} aria-label="Saved scenario"><option value="">Choose a scenario</option>{saved.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><button onClick={refreshSaved}>Refresh list</button></div>{saved.length===0&&<div className="empty-state"><Database size={28}/><strong>No scenarios loaded</strong><span>Save this case or refresh the account-backed list.</span></div>}</Panel></div></div><ScenarioCorrespondencePanel/><FinancialSensitivityLab/></>;
}

function ResearchAssistant({ section }: { section: string }) {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [busy, setBusy] = useState(false);
  async function submit(e: React.FormEvent) {
    e.preventDefault(); if (!prompt.trim()) return;
    setBusy(true); setResponse("");
    try { const r=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:prompt,context:{section,scenarioInputs:null,researchSources:[]}})}); const d=await r.json() as {reply?:string;error?:string}; setResponse(d.reply || d.error || "Chat is not available yet."); }
    catch { setResponse("Chat is not available yet."); } finally { setBusy(false); }
  }
  return <Sheet><SheetTrigger className="assistant-trigger"><Bot size={18}/><span>AI Research Assistant</span></SheetTrigger><SheetContent className="assistant-sheet"><SheetHeader><SheetTitle>AI Research Assistant</SheetTitle><SheetDescription>Research context and scenario inputs can be passed here as the model is developed.</SheetDescription></SheetHeader><div className="assistant-body"><div className="assistant-intro"><CircleHelp size={22}/><strong>Integration ready</strong><p>Chat requires a server-side API key and approved research context. Until then, no AI answer or unsupported research finding is shown.</p></div>{response&&<div className="chat-response" role="status">{response}</div>}</div><form className="assistant-form" onSubmit={submit}><label htmlFor="chat-prompt" className="sr-only">Ask a research question</label><textarea id="chat-prompt" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Ask about the decision framework…" /><button disabled={busy || !prompt.trim()} aria-label="Send question"><Send size={17}/></button></form></SheetContent></Sheet>;
}

export function SiteView({ section }: { section: string }) {
  const active = sections.find(s=>s.slug===section) || sections[0];
  const [menu, setMenu] = useState(false);
  const content: Record<string, React.ReactNode> = { overview:<Overview/>,demand:<Demand/>,architecture:<Architecture/>,location:<Location/>,economics:<Economics/>,"risk-delivery":<RiskDelivery/>,"scenario-lab":<ScenarioLab/> };
  return <div className="site-shell"><div className="topline"/><header className="site-header"><Link href="/" className="brand"><span className="brand-mark">UC</span><span><strong>University Consortium</strong><small>AI INFRASTRUCTURE STRATEGY</small></span></Link><div className="header-right"><span className="document-status"><span/> WORKING DRAFT · STEP 1–10</span><ResearchAssistant section={section}/><button className="menu-button" onClick={()=>setMenu(!menu)} aria-label={menu?"Close navigation":"Open navigation"}>{menu?<X size={20}/>:<Menu size={20}/>}</button></div></header><nav className={`site-nav ${menu?"nav-open":""}`} aria-label="Main navigation">{sections.map(s=><Link key={s.slug} href={path(s.slug)} onClick={()=>setMenu(false)} className={active.slug===s.slug?"active":""}><small>{s.number}</small>{s.label}</Link>)}</nav><main className="main-content"><div className="page-heading"><div><div className="eyebrow">{active.number} / DECISION FRAMEWORK</div><h1>{active.label}</h1><p>{active.question}</p></div><div className="page-heading-right"><Tag>{["demand","architecture","economics","scenario-lab"].includes(section)?"Illustrative estimates":section==="overview"?"Conditional recommendation":"Decision gates open"}</Tag><span>25 MW = confirmed total facility target</span></div></div>{content[active.slug]}</main><footer><span>University Consortium AI Data Center · Research framework</span><span>Conditional research as of {decisionData.as_of}; site and capital approval TBD</span></footer></div>;
}
